const evt = $input.first().json.body || $input.first().json;
if (evt.type !== 'checkout.session.completed') {
  return []; // ignore other events
}
const s = evt.data.object;
const fields = {};
for (const f of (s.custom_fields || [])) {
  fields[f.key] = (f.text && f.text.value) || (f.dropdown && f.dropdown.value) || '';
}
const businessName = fields.business_name || s.metadata?.business_name || '';
const industry = fields.industry || s.metadata?.industry || '';
const email = s.customer_details?.email || s.customer_email;
if (!email) throw new Error('No customer email on session');
const id = (s.customer || s.id).toString().replace(/[^a-zA-Z0-9_-]/g, '');
return [{ json: {
  id,
  email,
  business_name: businessName,
  industry,
  stripe_customer: s.customer,
  stripe_session: s.id,
  status: 'active',
  created_at: new Date().toISOString(),
  last_scanned: null,
  known_marks_snapshot: []
} }];
